using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad]
public static class BossVerification
{
 static BossVerification(){EditorApplication.playModeStateChanged+=s=>{if(!SessionState.GetBool("BossV2.Run",false))return;if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("Boss direct verification").AddComponent<BossVerificationRunner>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("BossV2.Run",false);EditorApplication.Exit(SessionState.GetInt("BossV2.Exit",1));}};}
 public static void Run(){if(File.Exists("Validation/S3-09-boss-v2-rerun.txt"))throw new IOException("Preserve evidence");SessionState.SetBool("BossV2.Run",true);EditorSceneManager.OpenScene("Assets/Scenes/C04.unity");EditorApplication.delayCall+=()=>EditorApplication.isPlaying=true;}
}
public sealed class BossVerificationRunner:MonoBehaviour
{
 readonly List<string> lines=new(),errors=new();Keyboard kb;
 PlayerInputReader Player=>RoomSession.Instance.Player;Rigidbody2D Body=>Player.GetComponent<Rigidbody2D>();BossEncounter Boss=>FindFirstObjectByType<BossEncounter>();
 void Check(bool ok,string text){if(!ok)throw new Exception(text);lines.Add("PASS: "+text);}
 void Log(string msg,string stack,LogType type){if(type is LogType.Error or LogType.Exception or LogType.Assert)errors.Add(msg+stack);}
 IEnumerator Start(){DontDestroyOnLoad(gameObject);Application.logMessageReceived+=Log;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;kb=InputSystem.AddDevice<Keyboard>();var stack=new Stack<IEnumerator>();stack.Push(Tests());bool fail=false;while(stack.Count>0&&!fail){object next=null;try{if(!stack.Peek().MoveNext()){stack.Pop();continue;}next=stack.Peek().Current;}catch(Exception e){fail=true;lines.Add(e.ToString());}if(next is IEnumerator child)stack.Push(child);else if(!fail)yield return next;}Application.logMessageReceived-=Log;InputSystem.RemoveDevice(kb);fail|=errors.Count>0;lines.AddRange(errors);lines.Add("Error/Exception/Assert "+errors.Count);lines.Insert(0,(fail?"FAIL ":"PASS ")+"S3-09 boss v2 rerun Unity="+Application.unityVersion);File.WriteAllLines("Validation/S3-09-boss-v2-rerun.txt",lines);SessionState.SetInt("BossV2.Exit",fail?1:0);EditorApplication.isPlaying=false;}
 IEnumerator Until(Func<bool> test,float seconds=6){double end=Time.realtimeSinceStartupAsDouble+seconds;while(!test()){if(Time.realtimeSinceStartupAsDouble>end)throw new Exception("Timed out waiting for boss scenario");yield return null;}}
 IEnumerator Keys(params Key[] keys){InputSystem.QueueStateEvent(kb,new KeyboardState(keys));yield return null;yield return new WaitForFixedUpdate();}
 void Place(Vector2 p){Player.ClearTransientInput();Player.transform.position=p;Body.position=p;Body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 IEnumerator Ready(){yield return Until(()=>RoomSession.Instance?.Player!=null&&!RoomSession.Instance.Transitioning&&!RoomSession.Instance.Respawning);yield return new WaitForSeconds(.15f);}
 IEnumerator Door(string target){var exit=Array.Find(FindObjectsByType<RoomExit>(FindObjectsSortMode.None),e=>e.destinationRoomId==target);Check(exit!=null&&exit.enabled,"enabled door "+target);Place(exit.transform.position);yield return new WaitForFixedUpdate();yield return null;yield return Until(()=>RoomSession.Instance.CurrentRoomId==target&&!RoomSession.Instance.Transitioning);yield return Ready();Check(FindObjectsByType<PlayerInputReader>(FindObjectsSortMode.None).Length==1,"single player after "+target);}
 IEnumerator RecoveryAttack(){var boss=Boss;int before=boss.Hits;yield return Keys(UnityEngine.InputSystem.Key.RightArrow);yield return Keys();Place(new Vector2(15.75f,1.81f));double finish=boss.PhaseStarted+boss.tuning.recovery;while(Time.timeAsDouble+.19<finish&&boss.HP>0){yield return Keys(UnityEngine.InputSystem.Key.X);yield return Keys();yield return new WaitForSeconds(.36f);}lines.Add($"MEASURE direct recovery attacks hits={boss.Hits-before}; playerFront={Body.position.x+.4f:F3}, bossFront=16.5; recovery={boss.tuning.recovery:F3}s");Check(boss.Hits>before,"recovery in-range X lands at least once");Place(new Vector2(8,1.81f));}
 IEnumerator Tests(){yield return new WaitForSeconds(.3f);var session=RoomSession.Instance;var health=Player.GetComponent<PlayerHealth>();var cp=FindFirstObjectByType<Checkpoint>();Place(cp.transform.position);yield return new WaitForSeconds(.15f);Check(session.CheckpointId=="CP-C04","CP-C04 selected before combat");Player.GetComponent<PlayerDash>().hasDash=true;Player.GetComponent<PlayerMotor>().hasDoubleJump=true;
  yield return Door("C06");Check(Boss.HP==20&&Boss.State==BossEncounter.Phase.Idle&&Boss.leftExit.enabled,"fresh boss idle HP20 unlocked");
  var rig=FindFirstObjectByType<RoomCameraRig>();Check(rig.orthographicSize==5.5f&&rig.horizontalLead==0&&rig.damping==.15f,"common camera values untouched");
  foreach(var resolution in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){rig.OutputCamera.aspect=(float)resolution.x/resolution.y;foreach(float x in new[]{3.5f,4.9f}){Place(new Vector2(x,1.81f));rig.BindAndSnap(Player);yield return null;foreach(var point in new[]{new Vector3(16.5f,1,0),new Vector3(18.5f,4,0),new Vector3(13.5f,1,0),new Vector3(16.5f,2,0),new Vector3(1,1,0)}){var v=rig.OutputCamera.WorldToViewportPoint(point);Check(v.x>=0&&v.x<=1&&v.y>=0&&v.y<=1,$"actual camera viewport {resolution} playerX={x} point={point}");}}}
  Place(new Vector2(3.5f,1.81f));yield return Door("C04");yield return Door("C06");var boss=Boss;
  Place(new Vector2(14.3f,1.81f));yield return Until(()=>boss.State==BossEncounter.Phase.MeleeTell);Check(!boss.leftExit.enabled&&boss.warning.enabled,"cross x5 locks and shows tell");Check(boss.MeleeBounds.min.x==13.5f&&boss.MeleeBounds.max.x==16.5f,"melee exact front3u");yield return Keys(UnityEngine.InputSystem.Key.LeftArrow);yield return new WaitForSeconds(.5f);yield return Keys(UnityEngine.InputSystem.Key.C);yield return Keys();int hp=health.HP;yield return Until(()=>boss.State==BossEncounter.Phase.MeleeRecovery);lines.Add($"MEASURE melee tell={boss.LastPhaseDuration:F4}s dash x={Body.position.x:F3}");Check(Math.Abs(boss.LastPhaseDuration-.8)<.05&&health.HP==hp&&Body.position.x<13.1f,"tell .8 and dash avoids");yield return RecoveryAttack();
  yield return Until(()=>boss.State==BossEncounter.Phase.WaveTell);Check(Math.Abs(boss.LastPhaseDuration-1.2)<.05,"melee recovery1.2");Place(new Vector2(14.4f,1.81f));yield return Keys();yield return Until(()=>Time.timeAsDouble-boss.PhaseStarted>=.88);yield return Keys(UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.16f);yield return Keys();yield return Until(()=>boss.LiveWave!=null);var wave=boss.LiveWave;Check(Math.Abs(boss.LastPhaseDuration-1)<.05&&Math.Abs(wave.GetComponent<BoxCollider2D>().bounds.size.y-1)<.01,"wave tell1 and height1");float startX=wave.transform.position.x;double start=Time.fixedTimeAsDouble;yield return new WaitForSeconds(.12f);Check(wave!=null,"wave survives ground contact");float speed=(startX-wave.transform.position.x)/(float)(Time.fixedTimeAsDouble-start);lines.Add($"MEASURE wave speed={speed:F4}u/s");Check(Math.Abs(speed-5)<.15&&health.HP==hp,"speed5 and jump avoids");
  Player.SetPaused(true);float wx=wave.transform.position.x;double time=Time.timeAsDouble;yield return new WaitForSecondsRealtime(.2f);Check(wave!=null&&wave.transform.position.x==wx&&Time.timeAsDouble==time,"Pause freezes wave and pattern");Player.SetPaused(false);Place(new Vector2(8,5));yield return Until(()=>boss.LiveWave==null,5);Check(boss.LiveWave==null,"wave destroyed at left wall / null-safe");
  Place(new Vector2(15.5f,1.81f));yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.Z);yield return new WaitForSeconds(.9f);yield return Keys();lines.Add($"MEASURE rear entry x={Body.position.x:F3} feet={Body.position.y-.8f:F3}");Check(Body.position.x<18.9f,"no entry into .5u rear gap");health.RestoreMax();Place(new Vector2(17.5f,4.81f));yield return new WaitForSeconds(.12f);Check(health.HP<5,"boss top contact damage1");Place(new Vector2(8,1.81f));health.RestoreMax();
  yield return Until(()=>boss.State==BossEncounter.Phase.MeleeRecovery);Place(new Vector2(11.3f,1.81f));int before=boss.Hits;yield return Keys(UnityEngine.InputSystem.Key.RightArrow);yield return new WaitForSeconds(.6f);yield return Keys(UnityEngine.InputSystem.Key.RightArrow,UnityEngine.InputSystem.Key.X);yield return Keys();yield return new WaitForSeconds(.25f);lines.Add($"MEASURE dash-location walk+X hits={boss.Hits-before} x={Body.position.x:F3} (informational only)");Place(new Vector2(8,1.81f));
  Check(session.Die(),"boss death accepted");yield return Until(()=>session.CurrentRoomId=="C04"&&!session.Respawning,4);Check(health.HP==5,"death returns CP-C04 HP max");yield return Door("C06");boss=Boss;Check(boss.HP==20&&boss.State==BossEncounter.Phase.Idle&&boss.leftExit.enabled,"reentry resets HP and pattern unlock");Place(new Vector2(8,1.81f));yield return Until(()=>boss.Fighting);
  while(boss.HP>0){yield return Until(()=>boss.State==BossEncounter.Phase.MeleeRecovery||boss.State==BossEncounter.Phase.WaveRecovery);if(boss.State==BossEncounter.Phase.WaveRecovery)yield return new WaitForSeconds(.3f);yield return RecoveryAttack();if(boss.HP>0){yield return Until(()=>boss.State!=BossEncounter.Phase.MeleeRecovery&&boss.State!=BossEncounter.Phase.WaveRecovery);}}
  Check(boss.Hits==20&&boss.HP==0&&boss.State==BossEncounter.Phase.Defeated&&boss.leftExit.enabled,"20 actual X damage wins and unlocks");Check(session.Die()&&!session.Respawning,"defeat priority suppresses subsequent death");
  yield return Door("C04");yield return Door("C06");boss=Boss;Place(new Vector2(8,1.81f));yield return Until(()=>boss.Fighting);boss.ReceiveHit(19,Player.transform.position);Check(session.Die(),"same-frame death queued");boss.ReceiveHit(1,Player.transform.position);yield return null;Check(boss.State==BossEncounter.Phase.Defeated&&!session.Respawning,"same frame death first then boss HP0 wins");
  Check(Time.timeScale==1,"final timeScale1");lines.Add("F1 omitted after regression failure; physical gamepad / natural boss fight / perception not tested.");
 }
}
